shellCommands.command:
cd /workspace && cat >> app/globals.css <<'EOF'

/* ---------- View transitions ---------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* Let clicks pass through to the live page while a transition runs. */
::view-transition {
  pointer-events: none;
}

/* Shared element: product thumbnail <-> detail hero */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
  animation-timing-function: cubic-bezier(0.2, 0, 0, 1);
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}
/* Snapshots are stretched to the group size, so rounded corners/colors blend cleanly. */
::view-transition-old(.morph),
::view-transition-new(.morph) {
  height: 100%;
}

/* Suspense reveal: skeleton leaves downward, content arrives upward */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

/* Directional page navigation */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}
::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}
@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}
@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}
@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* ---------- Reduced motion ---------- */

@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(*),
  ::view-transition-new(*),
  ::view-transition-group(*),
  ::view-transition-image-pair(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}
EOF
npx tsc --noEmit -p . 2>&1 | tail -20; echo tsc=$?; timeout 300 npx next build 2>&1 | tail -25
